var questions=[["终于到周末，你最想先做什么？", ["关掉提醒，安静待一会儿", "找个没去过的地方走走", "约熟人吃顿舒服的饭", "把拖了很久的小事收个尾"]], ["临时空出两小时，你会？", ["一个人听歌或发呆", "出门晒太阳、逛公园", "给想念的人打个电话", "整理一个抽屉或做道菜"]], ["哪种安排最容易让你觉得累？", ["消息一直响，没有独处时间", "整天待在同一个空间", "热闹很多，却没人能说上话", "行程零散，总在处理临时小事"]], ["给自己一份小奖励，你更想要？", ["一段不被打扰的时间", "一张去附近小城的车票", "和朋友慢慢聊天的夜晚", "亲手完成一个小作品"]], ["周日晚上，哪件事会让你满足？", ["终于慢下来，没人催我", "今天看到了新的风景", "和在意的人好好相处了", "做完了一件具体的小事"]], ["下个周末只留一项活动，你选？", ["在家读几页书或听音乐", "去附近散步，换条路线", "约一位舒服的朋友见面", "做一顿饭，或照顾植物"]]];var results=[["静音小岛", "先把外界音量调低。", "留出一小时不安排任务；把消息提醒暂时静音；选一件可以随时停下的小事。", "不必把休息也做成打卡任务。"], ["漫游补给站", "换个场景，给周末一点新鲜感。", "选一条附近没走过的路线；出门二十分钟；不设打卡数量，觉得舒服就停。", "给行程留白，比排满景点更轻松。"], ["熟人充电局", "找一个相处舒服的人，慢慢待一会儿。", "只约一两位熟人；选不用赶时间的地方；提前说好这次不赶下一场。", "社交也可以短一点，按你的精力结束。"], ["小事完成派", "做完一件小事，让生活重新顺手。", "挑一件半小时能做完的小事；完成就停；留出剩下的时间自由安排。", "完成感不需要靠清空所有待办来换。"]];